/**
 * Hand-authored scene geometry in the reference's 1672 × 941 coordinates.
 * Palette sampled from clear sky, cloud highlights and the letter faces.
 * Cloud banks are independent contours; no bitmap, pixel table or image mask.
 */
export const SCENE_WIDTH = 1672;
export const SCENE_HEIGHT = 941;
