/** Source-coordinate offsets; quantized to prevent subpixel edge shimmer. */
export function cloudFrameAt(timeMs: number) {
  const t = Number.isFinite(timeMs) ? Math.max(0, timeMs) : 0;
  const snap = (value: number) => Math.round(value / 2) * 2 || 0;
  return formations.map((cloud) => {
    const phase = (t / cloud.period) * Math.PI * 2;
    const limit = Math.floor(cloud.drift / 2) * 2;
    return {
      x: Math.max(-limit, Math.min(limit, snap(Math.sin(phase) * cloud.drift * cloud.side))) || 0,
      y: snap((Math.cos(phase) - 1) * cloud.lift),
    };
  });
}
